#!/usr/bin/env bash
# test-bootstrap.sh: end-to-end tests of the bootstrap scripts.
#
# No network, no sleeps, no wall clock: gh is a stub on PATH (tests/stubs)
# that logs its argv and keeps GitHub's state in a JSON file, and the git
# remotes are local bare repos reached through BOOTSTRAP_GIT_BASE. The
# starter trees are copied in by the real copy-starter.sh, "merged" by moving
# the bare repo's main, and regenerated by the real regenerate.sh, which runs
# the exported repos' own generators on them. apply-settings.sh and
# install-machine.sh run against a second invented owner whose repos hold a
# fake engine and fake installers that log what they were asked to do.
# Everything happens under one temp dir, removed at the end, with a scratch
# HOME and GIT_CONFIG_GLOBAL.
#
# Run: bash tests/test-bootstrap.sh
# Exit 0 and "N assertions passed" mean it worked; each failed assertion
# prints FAIL and the exit code is 1.

set -uo pipefail
export PYTHONDONTWRITEBYTECODE=1   # no __pycache__ in a tree that copy-starter.sh may copy
# The tools the scripts under test need (their require_tools lines) and this
# test's own: a missing one fails here in one line, not as hundreds of FAILs.
# TEST_BOOTSTRAP_TOOLS_ONLY=1 runs only this check (the test below runs it).
check_tools() {
  local t miss=()
  for t in git jq python3 node npm; do command -v "$t" >/dev/null 2>&1 || miss+=("$t"); done
  if command -v python3 >/dev/null 2>&1 && ! python3 -c 'import yaml' >/dev/null 2>&1; then miss+=("python3's yaml module (PyYAML)"); fi
  if [ "${#miss[@]}" -gt 0 ]; then
    printf 'test-bootstrap.sh: not run: missing %s on PATH; install it and run this again\n' "$(printf '%s, ' "${miss[@]}" | sed 's/, $//')" >&2
    return 2
  fi
}
check_tools || exit 2
[ -z "${TEST_BOOTSTRAP_TOOLS_ONLY:-}" ] || exit 0
B=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
K=$(cd "$B/.." && pwd)
# The add-content cases copy bootstrap/, starter/ and library/ with cp -R and
# write optional content into the copy. cp -R keeps a symlink a symlink, so a
# kit folder that is one (a scratch tree linked into a checkout) would send
# those writes into the tree it points at.
for d in bootstrap starter library; do
  [ ! -L "$K/$d" ] || { printf 'ERROR: %s is a symlink: run the suite from a checkout or a full copy of the kit, or its add-content cases write through the link\n' "$K/$d" >&2; exit 2; }
done
T=$(mktemp -d "${TMPDIR:-/tmp}/bootstrap-test.XXXXXX")
trap 'rm -rf "$T"' EXIT
PASSES=0 FAILS=0
ok()   { PASSES=$((PASSES + 1)); }
bad()  { FAILS=$((FAILS + 1)); printf 'FAIL: %s\n' "$*"; }
assert()      { local d=$1; shift; if "$@" >/dev/null 2>&1; then ok; else bad "$d"; fi; }
assert_not()  { local d=$1; shift; if "$@" >/dev/null 2>&1; then bad "$d"; else ok; fi; }
assert_eq()   { if [ "$2" = "$3" ]; then ok; else bad "$1: expected [$3], got [$2]"; fi; }
has()         { grep -qF -- "$2" "$1"; }       # file contains text
writes()      { python3 -I -c '
import json, sys
n = 0
for line in open(sys.argv[1], encoding="utf-8"):
    a = json.loads(line)
    if a[0] == "api":
        m = a[a.index("-X") + 1] if "-X" in a else "GET"
        n += m != "GET"
    elif a[:2] in (["repo", "create"], ["variable", "set"], ["secret", "set"], ["pr", "create"]):
        n += 1
print(n)' "$1"; }
log_lines()   { wc -l < "$1" | tr -d ' '; }
since()       { tail -n +"$(($1 + 1))" "$GH_LOG" > "$T/delta"; writes "$T/delta"; }   # write calls after line N
jqs()         { jq -r "$1" "$GH_STUB_STATE"; }
jqset()       { jq "$1" "$GH_STUB_STATE" > "$T/s" && mv "$T/s" "$GH_STUB_STATE"; }

export PATH="$B/tests/stubs:$PATH"
export TMPDIR="$T/tmp" HOME="$T/home"; mkdir -p "$TMPDIR" "$HOME"
export GH_LOG="$T/gh.log" GH_STUB_STATE="$T/gh-state.json"
# Most cases read App installations as a GitHub App user token can; the
# "gh's own sign-in" case below unsets it and gets the real 403.
export GH_STUB_APP_USER_TOKEN=1
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL="$T/gitconfig"
export BOOTSTRAP_GIT_BASE="file://$T/remotes"
export GIT_AUTHOR_DATE=2026-01-01T00:00:00Z GIT_COMMITTER_DATE=2026-01-01T00:00:00Z
unset GH_TOKEN GITHUB_TOKEN CLAUDE_CONFIG_DIR ADOPT_STATE_FILE XDG_STATE_HOME GH_STUB_GIT_REMOTES
touch "$GH_LOG"
git config --global user.name "Test User"
git config --global user.email "test-user@example.com"
git config --global init.defaultBranch main
git config --global protocol.file.allow always

SCRIPTS=(create-repos.sh create-environments.sh create-apps.sh set-secrets.sh copy-starter.sh
         regenerate.sh apply-settings.sh install-machine.sh verify.sh status.sh add-content.sh update-kit.sh preflight.sh)
FLEET=(_agent-guidance repo-settings acsi-agentskills acsi-agentskills-private skills-evals wsl-automation)
O=acme-example
OUT="$T/out" ERR="$T/err"
run() { "$@" >"$OUT" 2>"$ERR"; }   # run a script, keep its stdout and stderr
cd "$K" || exit 1

# Unique values that must never leave the stubs' memory.
PEM_MARK="PEMBODY$(od -An -N8 -tx1 /dev/urandom | tr -d ' \n')"
CS_MARK="CLIENTSECRET$(od -An -N8 -tx1 /dev/urandom | tr -d ' \n')"
BEARER="bearer-$(od -An -N12 -tx1 /dev/urandom | tr -d ' \n')"
export GH_STUB_FAKE_PEM=$'-----BEGIN FAKE KEY-----\n'"$PEM_MARK"$'\n-----END FAKE KEY-----\n'
export GH_STUB_CLIENT_SECRET="$CS_MARK"
sha() { printf '%s' "$1" | sha256sum | cut -d' ' -f1; }
uid_of() { python3 -I -c 'import sys; print(5000 + sum(map(ord, sys.argv[1])))' "$1"; }   # the gh stub's user ids

new_config() { # path plan [owner]
  cat > "$1" <<EOF
# test config
OWNER=${3:-$O}
OWNER_TWO=${3:-$O}-two
OWNER_TYPE=user
PLAN=$2
CLAUDE_PLAN=max20x
TIME_ZONE=Europe/Berlin
OWNER_NAME=Acme Example
REPOS_DIR=$T/home/repos
EOF
}
CFG="$T/fleet.env"; new_config "$CFG" free

# ======================================================== syntax and lint
for s in "${SCRIPTS[@]}" lib/common.sh lib/pr.sh tests/stubs/gh; do
  assert "bash -n $s" bash -n "$B/$s"
done
if command -v shellcheck >/dev/null 2>&1; then
  for s in "${SCRIPTS[@]}"; do assert "shellcheck $s" shellcheck -x -S warning "$B/$s"; done
else
  echo "note: shellcheck not installed; skipped"
fi
for s in "${SCRIPTS[@]}"; do
  assert "$s has a usage header" grep -q "^# $s" "$B/$s"
  assert "$s uses set -euo pipefail" grep -qx 'set -euo pipefail' "$B/$s"
  assert "$s --help prints its usage" bash -c '"$1" "$2" --help | grep -qF "$3"' _ bash "$B/$s" "$s ["
done
for p in lib/substitute.py lib/plan_sizing.py lib/time_zone.py lib/repin.py lib/content.py lib/fleet_fragment.py render-quickstart.py tests/check-refs.py tests/check-steps.py tests/check-links.py \
         tests/check-catalog.py tests/check-guide-lists.py tests/check-branch-prefixes.py tests/check-one-owner.py tests/check-evals-refs.py tests/mdlinks.py tests/stubs/gh_stub.py; do
  assert "$p parses" python3 -I -c 'import ast, sys; ast.parse(open(sys.argv[1], encoding="utf-8").read())' "$B/$p"
done
assert "lib/guidance_pins.py parses" python3 -I -c 'import ast, sys; ast.parse(open(sys.argv[1], encoding="utf-8").read())' "$B/lib/guidance_pins.py"
# The bash >= 4.4 guard: the version test, and that a too-old bash stops before anything runs.
guard() { bash -c '. "$1"; bash_version_ok "$2" "$3"' _ "$B/lib/common.sh" "$1" "$2"; }
assert "bash 4.4 passes the version guard" guard 4 4
assert "bash 5.0 passes the version guard" guard 5 0
assert_not "bash 4.3 fails the version guard" guard 4 3
assert_not "bash 3.2 fails the version guard" guard 3 2
sed 's/bash_version_ok "${BASH_VERSINFO\[0\]}" "${BASH_VERSINFO\[1\]}"/bash_version_ok 3 2/' "$B/lib/common.sh" > "$T/old-bash-common.sh"
assert_not "the guard's call site was found to rewrite" cmp -s "$B/lib/common.sh" "$T/old-bash-common.sh"
bash -c '. "$1"; echo reached' _ "$T/old-bash-common.sh" >"$OUT" 2>"$ERR"; rc=$?
assert_eq "a too-old bash exits 1 when common.sh is sourced" "$rc" 1
assert_not "nothing after the guard runs" has "$OUT" reached
assert "the refusal names the version needed" has "$ERR" "needs bash 4.4 or later"
# No script keeps a write helper in a pipeline, where its count and its die would be lost in a subshell.
assert_not "no script pipes into set_value or run_write_stdin" grep -nE '\|[[:space:]]*(set_value|run_write_stdin)\b' \
  "${SCRIPTS[@]/#/$B/}" "$B/lib/common.sh" "$B/lib/pr.sh"

# ======================================================== config parsing
printf 'OWNER=acme-example\nPLAN=free\nTOKEN=x\n' > "$T/bad1.env"
assert_not "an unknown config key is refused" bash "$B/create-repos.sh" --config "$T/bad1.env" --dry-run
printf 'OWNER=$(touch %s/pwned)\nPLAN=free\n' "$T" > "$T/bad2.env"
assert_not "a shell expression as OWNER is refused" bash "$B/create-repos.sh" --config "$T/bad2.env" --dry-run
assert_not "the config is never sourced" test -e "$T/pwned"
printf 'OWNER=acme-example\nPLAN=cheap\n' > "$T/bad3.env"
assert_not "an invalid PLAN is refused" bash "$B/create-repos.sh" --config "$T/bad3.env" --dry-run
printf 'OWNER=acme-example\nPLAN=free\nGUIDANCE_SYNC_APP_ID=12x\n' > "$T/bad4.env"
assert_not "a non-numeric App id is refused" bash "$B/create-repos.sh" --config "$T/bad4.env" --dry-run
printf 'OWNER=acme-example\nPLAN=free\nANTHROPIC_WORKSPACE_ID=svac_EXAMPLE0000000001\n' > "$T/bad5.env"
assert_not "a federation id of the wrong shape is refused" bash "$B/create-repos.sh" --config "$T/bad5.env" --dry-run
printf 'OWNER=acme-example\nPLAN=free\nSITE_REPO=example.net\n' > "$T/bad6.env"
assert_not "a SITE_REPO that is neither none nor owner/name is refused" bash "$B/create-repos.sh" --config "$T/bad6.env" --dry-run
assert_eq "fleet.env.example says no website explicitly" "$(grep -c '^SITE_REPO=none$' "$B/fleet.env.example")" 1
assert_not "a missing config is refused" bash "$B/create-repos.sh" --config "$T/none.env" --dry-run
grep -v '^CLAUDE_PLAN=' "$CFG" > "$T/noplan.env"
run bash "$B/create-repos.sh" --config "$T/noplan.env" --dry-run; rc=$?
assert_eq "a config without CLAUDE_PLAN is refused" "$rc" 1
assert "the refusal names CLAUDE_PLAN" has "$ERR" "CLAUDE_PLAN is required"
sed 's/^CLAUDE_PLAN=.*/CLAUDE_PLAN=max/' "$CFG" > "$T/badplan.env"
assert_not "an invalid CLAUDE_PLAN is refused" bash "$B/create-repos.sh" --config "$T/badplan.env" --dry-run
assert_eq "fleet.env.example leaves CLAUDE_PLAN for the adopter" "$(grep -c '^CLAUDE_PLAN=$' "$B/fleet.env.example")" 1
# TIME_ZONE: no default; loader checks shape and the tz database; required where it is written.
assert_eq "fleet.env.example leaves TIME_ZONE for the adopter" "$(grep -c '^TIME_ZONE=$' "$B/fleet.env.example")" 1
for bad in 'Berlin' 'Europe/' 'europe berlin' 'Mars/Olympus' 'Europe/Berlin;x'; do
  sed "s|^TIME_ZONE=.*|TIME_ZONE=$bad|" "$CFG" > "$T/badtz.env"
  run bash "$B/create-repos.sh" --config "$T/badtz.env" --dry-run; rc=$?
  assert_eq "TIME_ZONE=$bad is refused" "$rc" 1
  assert "the refusal for TIME_ZONE=$bad says where and how" has "$ERR" "timedatectl show -p Timezone --value"
done
for good in UTC America/Chicago America/Argentina/Buenos_Aires Etc/GMT+5; do
  sed "s|^TIME_ZONE=.*|TIME_ZONE=$good|" "$CFG" > "$T/goodtz.env"
  run bash "$B/create-repos.sh" --config "$T/goodtz.env" --dry-run; rc=$?
  assert_eq "TIME_ZONE=$good is accepted" "$rc" 0
done
grep -v '^TIME_ZONE=' "$CFG" > "$T/notz.env"
run bash "$B/create-repos.sh" --config "$T/notz.env" --dry-run; rc=$?
assert_eq "a config without TIME_ZONE still loads (an existing setup stays green)" "$rc" 0
run bash "$B/copy-starter.sh" --config "$T/notz.env" --dry-run starter/agent-guidance "$O/_agent-guidance"; rc=$?
assert_eq "copy-starter refuses a config without TIME_ZONE" "$rc" 1
assert "the refusal names TIME_ZONE and fleet.env" has "$ERR" "TIME_ZONE is required"
# lib/time_zone.py: the one line, exactly once.
mkdir -p "$T/tz/scripts"; printf '# c\ntimezone: UTC\nweekday: 1\n' > "$T/tz/scripts/base-md-merge-window.yml"
assert "time_zone.py writes the zone" python3 -I "$B/lib/time_zone.py" "$T/tz" --zone Asia/Tokyo
assert_eq "the file now names the zone, once" "$(grep -c '^timezone: Asia/Tokyo$' "$T/tz/scripts/base-md-merge-window.yml")" 1
run python3 -I "$B/lib/time_zone.py" "$T/tz" --zone Asia/Tokyo; rc=$?
assert_eq "time_zone.py fails when the UTC line is not there" "$rc" 1
assert "and says which file" has "$ERR" "base-md-merge-window.yml"
printf 'timezone: UTC\ntimezone: UTC\n' > "$T/tz/scripts/base-md-merge-window.yml"
run python3 -I "$B/lib/time_zone.py" "$T/tz" --zone Asia/Tokyo; rc=$?
assert_eq "time_zone.py fails when the line is there twice" "$rc" 1
mkdir -p "$T/tz2"; assert "time_zone.py leaves a tree without the file alone" python3 -I "$B/lib/time_zone.py" "$T/tz2" --zone Asia/Tokyo
# skills-evals' explorer/display.json: its one "time_zone": "UTC", exactly once.
mkdir -p "$T/tz3/explorer"; cp "$B/../starter/skills-evals/explorer/display.json" "$T/tz3/explorer/"
assert_eq "the shipped display.json has the neutral zone" "$(jq -r .time_zone "$T/tz3/explorer/display.json")" UTC
assert "time_zone.py writes the zone into display.json" python3 -I "$B/lib/time_zone.py" "$T/tz3" --zone Asia/Tokyo
assert_eq "display.json now has the zone" "$(jq -r .time_zone "$T/tz3/explorer/display.json")" Asia/Tokyo
assert_eq "display.json keeps its repos" "$(jq -c .issue_repos "$T/tz3/explorer/display.json")" "$(jq -c .issue_repos "$B/../starter/skills-evals/explorer/display.json")"
run python3 -I "$B/lib/time_zone.py" "$T/tz3" --zone Asia/Tokyo; rc=$?
assert_eq "time_zone.py fails when display.json has no UTC entry" "$rc" 1
for plan in pro max5x ultra max20x; do
  assert_eq "fleet_worker_hours $plan" "$(bash -c '. "$1"; fleet_worker_hours "$2"' _ "$B/lib/common.sh" "$plan")" \
    "$(case $plan in pro) echo 168;; max5x) echo 12;; ultra|max20x) echo 3;; esac)"
done
for plan in pro max5x ultra max20x; do
  assert_eq "loop_worker_hours $plan" "$(bash -c '. "$1"; loop_worker_hours "$2"' _ "$B/lib/common.sh" "$plan")" \
    "$(case $plan in pro) echo 168;; *) echo 24;; esac)"
done
# The starter's fire workflow must accept each plan's value: run its step by
# hand with a URL but no bearer, so it stops at "not configured", after the
# value check and before any network call (with no URL at all, the Fleet
# worker is "not set up yet" and exits 0 before that point).
python3 -I -c 'import sys, yaml; print(yaml.safe_load(open(sys.argv[1]))["jobs"]["fire"]["steps"][0]["run"])' \
  "$B/../starter/agent-guidance/.github/workflows/fleet-worker-fire.yml" > "$T/fire-step.sh"
for plan in pro max5x max20x; do
  hours=$(bash -c '. "$1"; fleet_worker_hours "$2"' _ "$B/lib/common.sh" "$plan")
  WORKER=fleet EVERY_REQUIRED=false EVERY_VAR=FLEET_WORKER_EVERY_HOURS URL_VAR=FLEET_WORKER_FIRE_URL BEARER_VAR=FLEET_WORKER_FIRE_BEARER FLEET_BEARER= LOOP_BEARER= EVERY_HOURS=$hours GITHUB_EVENT_NAME=workflow_dispatch FIRE_URL=https://api.example.com/fire bash "$T/fire-step.sh" > "$T/fire-step.out" 2>&1
  assert "the starter's fire workflow accepts $plan's $hours hours" has "$T/fire-step.out" "not configured: secret FLEET_WORKER_FIRE_BEARER"
done
for plan in pro max5x max20x; do
  hours=$(bash -c '. "$1"; loop_worker_hours "$2"' _ "$B/lib/common.sh" "$plan")
  WORKER=loop EVERY_REQUIRED=true EVERY_VAR=LOOP_WORKER_EVERY_HOURS URL_VAR=LOOP_WORKER_FIRE_URL BEARER_VAR=LOOP_WORKER_FIRE_BEARER FLEET_BEARER= LOOP_BEARER= EVERY_HOURS=$hours EVALS_REPO=acme/skills-evals GITHUB_EVENT_NAME=workflow_dispatch FIRE_URL= bash "$T/fire-step.sh" > "$T/fire-step.out" 2>&1
  assert "the starter's fire workflow accepts the Loop worker's $hours hours on $plan" has "$T/fire-step.out" "not configured: variable"
  assert_not "the Loop worker's $hours hours on $plan are not refused" has "$T/fire-step.out" "must be 3, 6"
done

# ======================================================== the tool check
# With jq missing from PATH the test stops at once, naming it.
tb="$T/toolbin"; mkdir -p "$tb"
for t in bash git python3 node npm sed printf; do src=$(command -v "$t") && ln -sf "$src" "$tb/$t"; done
run env -i HOME="$HOME" PATH="$tb" TEST_BOOTSTRAP_TOOLS_ONLY=1 "$BASH" "$B/tests/test-bootstrap.sh"; rc=$?
assert_eq "the tool check exits 2 without jq" "$rc" 2
assert "it names jq in one line" grep -qx "test-bootstrap.sh: not run: missing jq on PATH; install it and run this again" "$ERR"
run env TEST_BOOTSTRAP_TOOLS_ONLY=1 "$BASH" "$B/tests/test-bootstrap.sh"; rc=$?
assert_eq "the tool check passes with every tool" "$rc" 0

# ======================================================== preflight.sh
# Tools are stubbed by a bin dir that is the whole PATH: symlinks to what
# should exist, tiny wrappers for what a test fakes. A tool left out is
# missing. PREFLIGHT_OS and PREFLIGHT_WSL pin the OS the fix lines are for.
PF_REAL_GIT=$(command -v git) PF_REAL_PY=$(command -v python3) PF_REAL_JQ=$(command -v jq)
mkpf() { # dir [tool ...]: PATH dir without the tools named
  local d=$1 t src; shift
  rm -rf "$d"; mkdir -p "$d"
  for t in bash env uname grep sed cat dirname mktemp rm chmod tr cut od head wc tar; do
    case " $* " in *" $t "*) continue ;; esac
    src=$(command -v "$t") && ln -s "$src" "$d/$t"
  done
  printf '#!/bin/sh\nexec "%s" "$@"\n' "$B/tests/stubs/gh" > "$d/gh"
  printf '#!/bin/sh\nif [ "$1" = --version ] && [ -n "${PF_GIT_VERSION:-}" ]; then echo "git version $PF_GIT_VERSION"; exit 0; fi\nexec "%s" "$@"\n' "$PF_REAL_GIT" > "$d/git"
  printf '#!/bin/sh\nif [ -n "${PF_NO_YAML:-}" ] && [ "$*" = "-I -c import yaml" ]; then exit 1; fi\nexec "%s" "$@"\n' "$PF_REAL_PY" > "$d/python3"
  printf '#!/bin/sh\nif [ -n "${PF_JQ_VERSION:-}" ] && [ "$1" = --version ]; then echo "jq-$PF_JQ_VERSION"; exit 0; fi\nexec "%s" "$@"\n' "$PF_REAL_JQ" > "$d/jq"
  for t in node npm claude; do printf '#!/bin/sh\nexit 0\n' > "$d/$t"; done
  for t in gh git python3 jq node npm claude; do
    case " $* " in *" $t "*) rm -f "$d/$t" ;; *) chmod +x "$d/$t" ;; esac
  done
}
PFBIN="$T/pf-bin"; mkpf "$PFBIN"
PFCFG="$T/pf.env"; new_config "$PFCFG" free
printf '[credential "https://github.com"]\n\thelper = !gh auth git-credential\n' > "$T/pf-gitconfig"
: > "$T/pf-all.out"
pf() { # [env VAR=value ...] -- args to preflight.sh: runs it on PFBIN with a pinned OS
  local e=()
  while [ $# -gt 0 ] && [ "$1" != -- ]; do e+=("$1"); shift; done
  shift
  run env "PATH=${PF_PATH:-$PFBIN}" PREFLIGHT_OS="${PF_OS:-debian}" PREFLIGHT_WSL=0 GIT_CONFIG_GLOBAL="$T/pf-gitconfig" "${e[@]}" "$BASH" "$B/preflight.sh" "$@"
  local rc=$?
  cat "$OUT" "$ERR" >> "$T/pf-all.out"
  return $rc
}
# TIME_ZONE left empty (a copy of the new fleet.env.example), absent, or valid.
sed -e 's/^OWNER=.*/OWNER=acme-example/' -e 's/^OWNER_TWO=.*/OWNER_TWO=acme-example/' -e 's/^PLAN=.*/PLAN=free/' \
  -e 's/^CLAUDE_PLAN=.*/CLAUDE_PLAN=pro/' -e "s|^REPOS_DIR=.*|REPOS_DIR=$T/home/repos|" "$B/fleet.env.example" > "$T/tz-empty.env"
assert_eq "the example's TIME_ZONE is empty in this copy" "$(grep -c '^TIME_ZONE=$' "$T/tz-empty.env")" 1
grep -v '^TIME_ZONE=' "$T/tz-empty.env" > "$T/tz-absent.env"
sed 's/^TIME_ZONE=.*/TIME_ZONE=Europe\/Berlin/' "$T/tz-empty.env" > "$T/tz-valid.env"
for v in empty absent valid; do
  pf -- --config "$T/tz-$v.env"; rc=$?
  assert_eq "preflight exits 0 with TIME_ZONE $v" "$rc" 0
  assert_not "preflight does not FAIL on TIME_ZONE $v" grep -q '^FAIL' "$OUT"
  run env ADOPT_STATE_FILE="$T/tz-state-$v.json" bash "$B/status.sh" --config "$T/tz-$v.env"; rc=$?
  assert_eq "status.sh exits 0 with TIME_ZONE $v" "$rc" 0
  if [ "$v" = valid ]; then
    assert_not "status.sh's step 0 is not undone by TIME_ZONE $v" grep -qi 'TIME_ZONE' "$OUT" "$ERR"
  fi
  run bash "$B/verify.sh" --config "$T/tz-$v.env" --only repos
  assert_not "verify.sh does not stop on TIME_ZONE $v" grep -qi 'TIME_ZONE' "$OUT" "$ERR"
  run bash "$B/copy-starter.sh" --config "$T/tz-$v.env" --dry-run starter/agent-guidance acme-example/_agent-guidance; rc=$?
  if [ "$v" = valid ]; then
    assert_not "copy-starter does not refuse on TIME_ZONE $v" grep -q 'TIME_ZONE' "$ERR"
  else
    assert_eq "copy-starter refuses with TIME_ZONE $v" "$rc" 1
    assert "its message says what to set and how to find it" has "$ERR" "timedatectl show -p Timezone --value"
  fi
done
# status.sh's step 0 asks for TIME_ZONE only while a copy step (4, 10, 12, 13) is
# not done: copy-starter.sh would refuse there. gh sees two states of the
# adopter's repos: none, and every base copy step's files on the default branch.
echo '{}' > "$T/tz-gh-none.json"
jq -n --slurpfile s "$B/steps.json" '{repos: ([$s[0].steps[] | select(.track == "base" and (.run | contains("copy-starter.sh")) and .check.type == "files") | .check.files[]]
  | group_by(.repo) | map({key: ("acme-example/" + .[0].repo), value: {full_name: ("acme-example/" + .[0].repo), name: .[0].repo, visibility: "public", private: false,
      default_branch: "main", has_commits: true, files: (map({key: .path, value: true}) | from_entries)}}) | from_entries)}' > "$T/tz-gh-copied.json"
tz_status() { # <tz variant> <gh state: none|copied>
