# ======================================================== copy-starter.sh
# Each fleet repo gets a bare remote holding the README create-repos.sh wrote.
for r in "${FLEET[@]}"; do
  g="$T/remotes/$O/$r.git"; git init -q --bare "$g"
  w="$T/tmp/init-$r"; git init -q "$w"
  bash -c '. "$1/lib/common.sh"; generated_readme "$2"' _ "$B" "$r" > "$w/README.md"
  git -C "$w" add -A && git -C "$w" commit -qm init && git -C "$w" push -q "$g" HEAD:main; rm -rf "$w"
done
tree_of() { bash -c '. "$1/lib/common.sh"; kit_tree "$2"' _ "$B" "$1"; }
merge() { # repo branch: what merging its pull request does (a fast-forward of main)
  local g="$T/remotes/$O/$1.git"
  git --git-dir="$g" merge-base --is-ancestor main "refs/heads/$2" && git --git-dir="$g" update-ref refs/heads/main "refs/heads/$2"
}
on_main() { git --git-dir="$T/remotes/$O/$1.git" show "main:$2"; }

CFG1="$T/fleet-one.env"; new_config "$CFG1" paid; sed -i '/^OWNER_TWO=/d' "$CFG1"
run bash "$B/copy-starter.sh" --config "$CFG1" starter/repo-settings "$O/repo-settings"; rc=$?
assert_eq "a tree naming the second owner is refused while OWNER_TWO is unset" "$rc" 1
run bash "$B/copy-starter.sh" --config "$CFGP" starter/repo-settings "other-owner/repo-settings"; rc=$?
assert_eq "copy-starter refuses a repo of another owner" "$rc" 1
before=$(git --git-dir="$T/remotes/$O/repo-settings.git" for-each-ref | wc -l)
n=$(log_lines "$GH_LOG")
run bash "$B/copy-starter.sh" --config "$CFGP" --dry-run starter/repo-settings "$O/repo-settings"; rc=$?
assert_eq "copy-starter dry run exits 0" "$rc" 0
assert_eq "copy-starter dry run pushes nothing" "$(git --git-dir="$T/remotes/$O/repo-settings.git" for-each-ref | wc -l)" "$before"
assert_eq "copy-starter dry run opens nothing" "$(since "$n")" 0
# Before any starter is merged no repo has its actions.lock: step 18's check
# is not done yet (it once passed vacuously from step 2 on).
run bash "$B/regenerate.sh" --config "$CFGP" --check actions-lock; rc=$?
assert_eq "actions-lock --check is not done before the starters are merged" "$rc" 1
assert "it says which lock is missing and why" has "$OUT" "acme-example/repo-settings has no .github/workflows/actions.lock yet (merge its starter pull request first)"
# Stand-ins for node and npm: the skills-evals copy rebuilds the explorer pages
# for TIME_ZONE (copy-starter.sh 2c), which needs the network for npm ci.
mkdir -p "$T/fakenode"
printf '#!/usr/bin/env bash\nprintf "npm %%s\\n" "$*" >> "%s"\nmkdir -p node_modules\n' "$T/node.log" > "$T/fakenode/npm"
printf '#!/usr/bin/env bash\nprintf "node %%s\\n" "$*" >> "%s"\n' "$T/node.log" > "$T/fakenode/node"
chmod +x "$T/fakenode/npm" "$T/fakenode/node"
for r in "${FLEET[@]}"; do
  t=$(tree_of "$r")
  if [ "$r" = skills-evals ]; then
    run env PATH="$T/fakenode:$PATH" bash "$B/copy-starter.sh" --config "$CFGP" "starter/$t" "$O/$r"; rc=$?
  else
    run bash "$B/copy-starter.sh" --config "$CFGP" "starter/$t" "$O/$r"; rc=$?
  fi
  assert_eq "copy-starter $t exits 0" "$rc" 0
  [ "$rc" = 0 ] || { printf '  copy-starter %s stderr (last 20 lines):\n' "$t"; tail -n 20 "$ERR" | sed 's/^/    /'; }
  g="$T/remotes/$O/$r.git"
  assert "copy-starter $t pushed starter/$t" git --git-dir="$g" rev-parse -q --verify "refs/heads/starter/$t"
