assert_eq "the element is appended to repos:, re-indented to its list" "$(fleet_names < "$fw/repo-settings/fleet.yml")" "o/one o/skills-evals"
assert "the element keeps its comment" grep -qx '  # inside' "$fw/repo-settings/fleet.yml"
assert "the rest of fleet.yml is kept" bash -c 'grep -qx "# trailing comment" "$1" && python3 -I -c "import sys, yaml; assert yaml.safe_load(open(sys.argv[1]))[\"defaults\"] == {\"x\": 1}" "$1"' _ "$fw/repo-settings/fleet.yml"
run python3 -I "$FF" check "$fw" o; rc=$?
assert_eq "fleet_fragment check passes after the merge" "$rc" 0
cp "$fw/repo-settings/fleet.yml" "$T/ff-merged.yml"
run python3 -I "$FF" merge "$fw"; rc=$?
assert_eq "a second merge exits 0" "$rc" 0
assert "a second merge changes nothing" cmp -s "$fw/repo-settings/fleet.yml" "$T/ff-merged.yml"
printf 'repos:\n  - name: o/skills-evals\n    manage: []\n' > "$fw/repo-settings/fleet.evals.yml"
run python3 -I "$FF" merge "$fw"; rc=$?
assert_eq "a fragment whose element fleet.yml declares merges to nothing" "$rc" 0
assert "fleet.yml keeps its own element" cmp -s "$fw/repo-settings/fleet.yml" "$T/ff-merged.yml"
assert_not "and the leftover fragment is deleted" test -e "$fw/repo-settings/fleet.evals.yml"
