assert "the registry's starter names a 40-hex gate ref and a 64-hex digest" bash -c '[[ $1 =~ ^[0-9a-f]{40}$ && $2 =~ ^[0-9a-f]{64}$ ]]' _ "$old_ref" "$old_sum"
