import re, sys, yaml
path, pats = sys.argv[1], sys.argv[2:]
text = open(path, encoding="utf-8").read()
keep = [l for l in text.splitlines(True) if not any(re.fullmatch(r"\s+- " + p + r"\s*", l) for p in pats)]
new = "".join(keep)
