  assert_eq "$c passes on the kit" "$rc" 0
done
run python3 -I "$B/render-quickstart.py" --check; rc=$?
assert_eq "the quick start table matches steps.json" "$rc" 0
# A scratch kit: copies of everything the checkers read, the exports linked.
mk_kit() {
  rm -rf "$T/kit"; mkdir -p "$T/kit"
  cp -a "$K/README.md" "$K/LICENSE" "$K/docs" "$K/bootstrap" "$K/.claude" "$T/kit/"
  ln -s "$K/starter" "$T/kit/starter"; ln -s "$K/export" "$T/kit/export"; ln -s "$K/library" "$T/kit/library"
  ln -s "$K/run-all-tests.sh" "$T/kit/run-all-tests.sh"
}
kb() { python3 -I "$T/kit/bootstrap/$1" "${@:2}" >"$OUT" 2>&1; }
mk_kit
kb tests/check-links.py "$T/kit"; rc=$?
assert_eq "check-links passes on the unchanged scratch kit" "$rc" 0
kb tests/check-steps.py "$T/kit"; rc=$?
assert_eq "check-steps passes on the unchanged scratch kit" "$rc" 0
printf '\nSee [nowhere](docs/nope.md) and [no anchor](docs/routines.md#no-such-heading).\n' >> "$T/kit/README.md"
kb tests/check-links.py "$T/kit"
assert "check-links fails on a missing file" has "$OUT" "docs/nope.md does not exist"
assert "check-links fails on a missing anchor" has "$OUT" "has no heading #no-such-heading"
mk_kit
sed -i 's/42 steps (27 base,/43 steps (27 base,/' "$T/kit/docs/before-you-start.md"
kb tests/check-steps.py "$T/kit"; rc=$?
assert_eq "check-steps fails on a wrong step count in before-you-start.md" "$rc" 1
assert "check-steps names the expected counts" has "$OUT" "42 steps (27 base, 15 evals)"
mk_kit
jq '.steps[3].link = "docs/settings-and-apps.md#no-such-heading" | .steps[4].phase = 3 | .steps[5].check.groups = ["rulesets"]' \
  "$K/bootstrap/steps.json" > "$T/kit/bootstrap/steps.json"
kb tests/check-steps.py "$T/kit"; rc=$?
assert_eq "check-steps fails on a bad steps.json" "$rc" 1
assert "check-steps names the broken anchor" has "$OUT" "has no heading #no-such-heading"
assert "check-steps names the old guide's field" has "$OUT" "step 4: no fields from the old guide"
assert "check-steps names the unknown verify group" has "$OUT" "verify group 'rulesets'"
mk_kit
jq '(.steps[] | select(.id == "3") | .track) = "both" | (.steps[] | select(.id == "4")) |= del(.track)
    | (.steps[] | select(.id == "6") | .check.groups) += ["apps:roster"]
    | (.steps[] | select(.id == "33") | .check.groups) -= ["apps:roster"]
    | (.steps[] | select(.id == "35") | .check.groups) += ["regen:skills-locks"]
    | (.steps[] | select(.id == "37") | .check.groups) -= ["environments"]
    | (.steps[] | select(.id == "36") | .check.files) += [{"repo": "wsl-automation", "path": "scripts/unix/install-schedule.sh"}]' \
  "$K/bootstrap/steps.json" > "$T/kit/bootstrap/steps.json"
kb tests/check-steps.py "$T/kit"; rc=$?
assert_eq "check-steps fails on bad tracks" "$rc" 1
assert "check-steps names a track that is not base or evals" has "$OUT" "step 3: track is one of ['base', 'evals']: 'both'"
assert "check-steps names a step with no track" has "$OUT" "step 4: track is one of ['base', 'evals']: None"
assert "check-steps names a base step checking what only evals has" has "$OUT" "step 6 (base): apps:roster checks something on the base track"
assert "check-steps names an evals step checking what only the base has" has "$OUT" "step 35 (evals): regen:skills-locks checks something on the evals track"
assert "check-steps names an evals need no earlier evals step checks" has "$OUT" "step 34 (evals): installs:roster needs ['evals:apps:roster']"
assert "check-steps names an evals environment no earlier evals step creates" has "$OUT" "step 25 (evals): values:routine-fire needs ['evals:environments']"
assert "check-steps names a files entry both tracks check" has "$OUT" "no files entry is checked by a base and an evals step: ['files:wsl-automation:scripts/unix/install-schedule.sh']"
bash "$T/kit/bootstrap/status.sh" --config "$CFGP" >"$OUT" 2>"$ERR"; rc=$?
assert_eq "status refuses a step with an unknown track" "$rc" 1
assert "status names the step and its track" has "$ERR" "step 3 has an unknown track: both"
kb render-quickstart.py --check; rc=$?
assert_eq "render-quickstart --check fails on a stale table" "$rc" 1
mk_kit
jq '(.items[] | select(.id == "security") | .tier) = "core" | del(.items[] | select(.id == "rules-dir"))' \
  "$K/bootstrap/content-catalog.json" > "$T/kit/bootstrap/content-catalog.json"
kb tests/check-catalog.py "$T/kit"; rc=$?
assert_eq "check-catalog fails on a catalog that disagrees with the kit" "$rc" 1
assert "check-catalog names a library folder the catalog does not offer" has "$OUT" "extra: ['rules-dir']"
assert "check-catalog names an optional item turned core" has "$OUT" "extra: ['security']"
assert "check-catalog names a core item that is not in starter/" has "$OUT" "security: the core section has its eval-coverage row"
mk_kit
grep -vF '| `wsl-automation` | The Codex Cloud bootstrap pin |' "$K/docs/generated-files.md" > "$T/kit/docs/generated-files.md"
kb tests/check-guide-lists.py "$T/kit"; rc=$?
assert_eq "check-guide-lists fails when a REGENERATE.md item has no step" "$rc" 1
mk_kit
grep -vF '"acsi-agentskills|-|secret|PRIVACY_DENYLIST|file"' "$K/bootstrap/lib/common.sh" > "$T/kit/bootstrap/lib/common.sh"
kb tests/check-refs.py; rc=$?
assert_eq "check-refs fails when a secret a workflow reads has no setter" "$rc" 1
assert "check-refs names the secret" has "$OUT" "PRIVACY_DENYLIST"
mk_kit
sed -i 's/claude\/scaffold-\*/claude\/scaffolding-*/' "$T/kit/docs/evals-and-loop.md"
kb tests/check-branch-prefixes.py; rc=$?
assert_eq "check-branch-prefixes fails when the docs name a lane wrong" "$rc" 1

# ======================================================== secrets never leave the stubs
assert_not "no private key, client secret or bearer is in any file the run wrote" grep -rqF -e "$PEM_MARK" -e "$CS_MARK" -e "$BEARER" "$T" --exclude-dir=kit
assert_not "fleet.env holds no secret" grep -qiE 'pem|secret|bearer|denylist' "$CFGP"

printf '%d assertions passed, %d failed\n' "$PASSES" "$FAILS"
[ "$FAILS" = 0 ]
